-- migra-083 — candidato solo con votos: al menos delta_min_votes votos netos que cuentan (26/09/2026). Con la raiz, un solo voto daba δ = 1 y
-- alcanzaba el umbral (aviso de un lector externo); la puerta pasa a estar en votos, no en δ, y el bonus del tema no sustituye a ninguno.
-- Ademas repara los apostrofos perdidos en ca/fr/it en cuatro parrafos de «El ciclo» de la migra-080 (error del generador de textos).
INSERT IGNORE INTO config (ckey, cvalue, descr) VALUES ('delta_min_votes', '2', 'Votos netos que cuentan (eff_pos - eff_neg) necesarios para ser candidato a portada; el bonus del tema no sustituye a ninguno');

UPDATE pages SET body = REPLACE(body, '<p><b>1. Del radar a la portada.</b> Els cicles es tornen: un publica a Mitjans, el següent a Substacks, i així successivament. A cada cicle, entre els enviaments de la portada a què li toca que fa almenys <b>{minage} minuts</b> que són al radar i tenen un δ dalmenys <b>{minpub}</b> (Mitjans) o <b>{minpubs}</b> (Substacks), sen publica <b>un de sol</b>, triat <b>a sorts</b>: cada candidat té tantes paperetes com δ, així que el de major δ és el més probable, però no està garantit, i els que el segueixen també surten de vegades. Sense vots no shi arriba. Si a la portada del torn no li arriba res, el torn passa a laltra; si tampoc, aquell cicle no es publica res: la portada no somple per omplir. El temps mínim existeix perquè un enviament no pugi només perquè va arribar en un moment tranquil; ha de ser vist i votat abans.</p>', '<p><b>1. Del radar a la portada.</b> Els cicles es tornen: un publica a Mitjans, el següent a Substacks, i així successivament. A cada cicle, entre els enviaments de la portada a què li toca que fa almenys <b>{minage} minuts</b> que són al radar i tenen un δ d''almenys <b>{minpub}</b> (Mitjans) o <b>{minpubs}</b> (Substacks), se''n publica <b>un de sol</b>, triat <b>a sorts</b>: cada candidat té tantes paperetes com δ, així que el de major δ és el més probable, però no està garantit, i els que el segueixen també surten de vegades. Sense vots no s''hi arriba. Si a la portada del torn no li arriba res, el torn passa a l''altra; si tampoc, aquell cicle no es publica res: la portada no s''omple per omplir. El temps mínim existeix perquè un enviament no pugi només perquè va arribar en un moment tranquil; ha de ser vist i votat abans.</p>') WHERE slug = 'algoritmo.ca';
UPDATE pages SET body = REPLACE(body, '<p><b>Quan, exactament.</b> Dins de cada tram de {cycle} minuts, el minut en què corre el cicle canvia i no sanuncia; {site} diu «abans de les tal i tal». Així ningú no pot guardar-se els vots per deixar-los anar un segon abans: qui vulgui guanyar ha de convèncer, no cronometrar. I com que és un sorteig, tampoc no serveix afinar lúltim vot per treure-li una dècima al del costat.</p>', '<p><b>Quan, exactament.</b> Dins de cada tram de {cycle} minuts, el minut en què corre el cicle canvia i no s''anuncia; {site} diu «abans de les tal i tal». Així ningú no pot guardar-se els vots per deixar-los anar un segon abans: qui vulgui guanyar ha de convèncer, no cronometrar. I com que és un sorteig, tampoc no serveix afinar l''últim vot per treure-li una dècima al del costat.</p>') WHERE slug = 'algoritmo.ca';
UPDATE pages SET body = REPLACE(body, '<p><b>2. Caducitat.</b> El que passa <b>{newttltxt}</b> al radar sense arribar a portada sarxiva: el radar tampoc no és per sempre.</p>', '<p><b>2. Caducitat.</b> El que passa <b>{newttltxt}</b> al radar sense arribar a portada s''arxiva: el radar tampoc no és per sempre.</p>') WHERE slug = 'algoritmo.ca';
UPDATE pages SET body = REPLACE(body, '<p><b>4. Arxiu.</b> El que fa {ttltxt} que és a portada sarxiva. Es pot continuar llegint, però ja no es vota ni es comenta: la conversa va ser el que va ser.</p>', '<p><b>4. Arxiu.</b> El que fa {ttltxt} que és a portada s''arxiva. Es pot continuar llegint, però ja no es vota ni es comenta: la conversa va ser el que va ser.</p>') WHERE slug = 'algoritmo.ca';
UPDATE pages SET body = REPLACE(body, '<p><b>1. Du radar à la une.</b> Les cycles alternent : lun publie sur Médias, le suivant sur Substacks, et ainsi de suite. À chaque cycle, parmi les envois de la une dont cest le tour qui sont dans le radar depuis au moins <b>{minage} minutes</b> et ont un δ dau moins <b>{minpub}</b> (Médias) ou <b>{minpubs}</b> (Substacks), <b>un seul</b> est publié, choisi <b>au sort</b> : chaque candidat a autant de billets que de δ, si bien que le plus grand δ est le plus probable, mais pas garanti, et ceux qui le suivent sortent aussi parfois. Sans votes, on ny arrive pas. Si la une dont cest le tour na rien de prêt, le tour passe à lautre ; si elle non plus, rien nest publié ce cycle-là : on ne remplit pas la une pour la remplir. Le temps minimum existe pour quun envoi ne monte pas seulement parce quil est arrivé à un moment calme ; il doit être vu et voté avant.</p>', '<p><b>1. Du radar à la une.</b> Les cycles alternent : l''un publie sur Médias, le suivant sur Substacks, et ainsi de suite. À chaque cycle, parmi les envois de la une dont c''est le tour qui sont dans le radar depuis au moins <b>{minage} minutes</b> et ont un δ d''au moins <b>{minpub}</b> (Médias) ou <b>{minpubs}</b> (Substacks), <b>un seul</b> est publié, choisi <b>au sort</b> : chaque candidat a autant de billets que de δ, si bien que le plus grand δ est le plus probable, mais pas garanti, et ceux qui le suivent sortent aussi parfois. Sans votes, on n''y arrive pas. Si la une dont c''est le tour n''a rien de prêt, le tour passe à l''autre ; si elle non plus, rien n''est publié ce cycle-là : on ne remplit pas la une pour la remplir. Le temps minimum existe pour qu''un envoi ne monte pas seulement parce qu''il est arrivé à un moment calme ; il doit être vu et voté avant.</p>') WHERE slug = 'algoritmo.fr';
UPDATE pages SET body = REPLACE(body, '<p><b>Quand, exactement.</b> Dans chaque tranche de {cycle} minutes, la minute où tourne le cycle change et nest pas annoncée ; {site} dit « avant telle heure ». Ainsi personne ne peut garder ses votes pour les lâcher une seconde avant : qui veut gagner doit convaincre, pas chronométrer. Et comme cest un tirage, peaufiner le dernier vote pour prendre un dixième au voisin ne sert à rien non plus.</p>', '<p><b>Quand, exactement.</b> Dans chaque tranche de {cycle} minutes, la minute où tourne le cycle change et n''est pas annoncée ; {site} dit « avant telle heure ». Ainsi personne ne peut garder ses votes pour les lâcher une seconde avant : qui veut gagner doit convaincre, pas chronométrer. Et comme c''est un tirage, peaufiner le dernier vote pour prendre un dixième au voisin ne sert à rien non plus.</p>') WHERE slug = 'algoritmo.fr';
UPDATE pages SET body = REPLACE(body, '<p><b>2. Expiration.</b> Ce qui passe <b>{newttltxt}</b> dans le radar sans arriver en une est archivé : le radar non plus nest pas pour toujours.</p>', '<p><b>2. Expiration.</b> Ce qui passe <b>{newttltxt}</b> dans le radar sans arriver en une est archivé : le radar non plus n''est pas pour toujours.</p>') WHERE slug = 'algoritmo.fr';
UPDATE pages SET body = REPLACE(body, '<p><b>4. Archive.</b> Ce qui est en une depuis {ttltxt} est archivé. On peut encore le lire, mais on ne vote plus et on ne commente plus : la conversation a été ce quelle a été.</p>', '<p><b>4. Archive.</b> Ce qui est en une depuis {ttltxt} est archivé. On peut encore le lire, mais on ne vote plus et on ne commente plus : la conversation a été ce qu''elle a été.</p>') WHERE slug = 'algoritmo.fr';
UPDATE pages SET body = REPLACE(body, '<p><b>1. Dal radar alla prima pagina.</b> I cicli si alternano: uno pubblica su Media, il successivo su Substack, e così via. In ogni ciclo, tra gli invii della prima pagina di turno che stanno nel radar da almeno <b>{minage} minuti</b> e hanno un δ di almeno <b>{minpub}</b> (Media) o <b>{minpubs}</b> (Substack), se ne pubblica <b>uno solo</b>, scelto <b>a sorte</b>: ogni candidato ha tanti biglietti quanto il suo δ, così quello con il δ maggiore è il più probabile, ma non è garantito, e anche quelli che lo seguono escono ogni tanto. Senza voti non si arriva. Se alla prima pagina di turno non arriva nulla, il turno passa allaltra; se nemmeno a quella, in quel ciclo non si pubblica nulla: la prima pagina non si riempie tanto per riempirla. Il tempo minimo esiste perché un invio non salga solo perché è arrivato in un momento tranquillo; deve essere visto e votato prima.</p>', '<p><b>1. Dal radar alla prima pagina.</b> I cicli si alternano: uno pubblica su Media, il successivo su Substack, e così via. In ogni ciclo, tra gli invii della prima pagina di turno che stanno nel radar da almeno <b>{minage} minuti</b> e hanno un δ di almeno <b>{minpub}</b> (Media) o <b>{minpubs}</b> (Substack), se ne pubblica <b>uno solo</b>, scelto <b>a sorte</b>: ogni candidato ha tanti biglietti quanto il suo δ, così quello con il δ maggiore è il più probabile, ma non è garantito, e anche quelli che lo seguono escono ogni tanto. Senza voti non si arriva. Se alla prima pagina di turno non arriva nulla, il turno passa all''altra; se nemmeno a quella, in quel ciclo non si pubblica nulla: la prima pagina non si riempie tanto per riempirla. Il tempo minimo esiste perché un invio non salga solo perché è arrivato in un momento tranquillo; deve essere visto e votato prima.</p>') WHERE slug = 'algoritmo.it';
UPDATE pages SET body = REPLACE(body, '<p><b>Quando, esattamente.</b> Dentro ogni tratto di {cycle} minuti, il minuto in cui gira il ciclo cambia e non si annuncia; {site} dice «prima delle tale e tale». Così nessuno può tenersi i voti per mollarli un secondo prima: chi vuole vincere deve convincere, non cronometrare. E siccome è un sorteggio, non serve nemmeno affinare lultimo voto per strappare un decimo al vicino.</p>', '<p><b>Quando, esattamente.</b> Dentro ogni tratto di {cycle} minuti, il minuto in cui gira il ciclo cambia e non si annuncia; {site} dice «prima delle tale e tale». Così nessuno può tenersi i voti per mollarli un secondo prima: chi vuole vincere deve convincere, non cronometrare. E siccome è un sorteggio, non serve nemmeno affinare l''ultimo voto per strappare un decimo al vicino.</p>') WHERE slug = 'algoritmo.it';

